class StdReader:
	def read_int(self):
		return int(self.read_string())

	def read_ints(self, sep=None):
		return [int(i) for i in self.read_strings(sep)]

	def read_float(self):
		return float(self.read_string())

	def read_floats(self, sep=None):
		return [float(i) for i in self.read_strings(sep)]

	def read_string(self):
		return input()

	def read_strings(self, sep=None):
		return self.read_string().split(sep)

reader = StdReader()


def main():
	n = reader.read_int()
	a = reader.read_ints()

	d = 1
	c = 0
	dd = 0
	i = 0

	collected = [False]*n

	while c < n:
		if a[i] <= c and not collected[i]:
			c += 1
			collected[i] = True
			# print('collected', i)

		if c == n:
			break

		if i == n - 1 and d == 1:
			d *= -1
			dd += 1
			# print('change end')
		if i == 0 and d == -1:
			d *= -1
			dd += 1
			# print('change front')

		i += d

	print(dd)


if __name__ == '__main__':
	main()

