```python
def solve():
    n, m = map(int, input().split())
    matrix = [[0] * n for _ in range(m)]
    for i in range(n):
        x, *bulbs = map(int, input().split())
        for bulb in bulbs:
            matrix[bulb - 1][i] = 1

    def gaussian_elimination(matrix):
        rows = len(matrix)
        cols = len(matrix[0])
        lead = 0
        for r in range(rows):
            if lead >= cols:
                return True
            i = r
            while matrix[i][lead] == 0:
                i += 1
                if i == rows:
                    i = r
                    lead += 1
                    if lead == cols:
                        return True
            matrix[i], matrix[r] = matrix[r], matrix[i]
            lv = matrix[r][lead]
