            for i in range(rows):
                if i != r:
                    lv = matrix[i][lead]
                    for j in range(cols):
                        matrix[i][j] = (matrix[i][j] + lv) % 2
            lead += 1
        return True

    if gaussian_elimination(matrix):
        print("YES")
    else:
        print("NO")

