def solve():
    n, m = map(int, input().split())
    grid = [list(input()) for _ in range(n)]

    start_row, start_col = -1, -1
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start_row, start_col = i, j
                break
        if start_row != -1:
            break

    path = []
    curr_row, curr_col = start_row, start_col
    visited = set()
    visited.add((curr_row, curr_col))

    while True:

        next_row, next_col = -1, -1

        # Check right
        if curr_col + 1 < m and grid[curr_row][curr_col + 1] == '*' and (curr_row, curr_col + 1) not in visited:
            next_row, next_col = curr_row, curr_col + 1
            path.append('R')
        # Check down
        elif curr_row + 1 < n and grid[curr_row + 1][curr_col] == '*' and (curr_row + 1, curr_col) not in visited:
            next_row, next_col = curr_row + 1, curr_col
            path.append('D')
        # Check left
        elif curr_col - 1 >= 0 and grid[curr_row][curr_col - 1] == '*' and (curr_row, curr_col - 1) not in visited:
            next_row, next_col = curr_row, curr_col - 1
            path.append('L')
        # Check up
        elif curr_row - 1 >= 0 and grid[curr_row - 1][curr_col] == '*' and (curr_row - 1, curr_col) not in visited:
            next_row, next_col = curr_row - 1, curr_col
            path.append('U')
        #Check back to start
        elif (next_row == -1 and next_col == -1):
            if (start_row == curr_row and start_col == curr_col):
                break

            if curr_col + 1 < m and grid[curr_row][curr_col + 1] == '*' and (curr_row, curr_col + 1) == (start_row, start_col):
                next_row, next_col = curr_row, curr_col + 1
                path.append('R')
            elif curr_row + 1 < n and grid[curr_row + 1][curr_col] == '*' and (curr_row + 1, curr_col) == (start_row, start_col):
                next_row, next_col = curr_row + 1, curr_col
                path.append('D')
            elif curr_col - 1 >= 0 and grid[curr_row][curr_col - 1] == '*' and (curr_row, curr_col - 1) == (start_row, start_col):
