        nim_sum = 0
        for cycle_size in cycles:
            if cycle_size > 1:
                if cycle_size == 2 or cycle_size == 3:
                    nim_sum ^= 1
                elif cycle_size == 4 or cycle_size == 6:
                    nim_sum ^= 2
                elif cycle_size == 5:
                    nim_sum ^= 0
                else:
                    nim_sum ^= (cycle_size % 2) 

        if nim_sum == 0:
