def solve():
    n, m, k = map(int, input().split())
    governments = list(map(int, input().split()))
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u, v))

    non_governments = [i for i in range(1, n + 1) if i not in governments]

    added_edges = 0

    # Connect non-government nodes to government nodes
    for ng in non_governments:
        for g in governments:
            if (ng, g) not in edges and (g, ng) not in edges:
                added_edges += 1

    # Connect non-government nodes to each other
    for i in range(len(non_governments)):
        for j in range(i + 1, len(non_governments)):
            u = non_governments[i]
            v = non_governments[j]
            if (u, v) not in edges and (v, u) not in edges:
                added_edges += 1

    print(added_edges)

solve()

