    for char in s:
        if char == '?':
            question_marks += 1
        else:
            counts[char] += 1

    if n % 4 != 0:
        print("===")
        return

    target_count = n // 4

    needed = {}
    for nucleotide in counts:
        needed[nucleotide] = target_count - counts[nucleotide]

    total_needed = sum(needed.values())

    if total_needed != question_marks:
        print("===")
        return

