def parse_comments(comments_string):
    comments = comments_string.split(',')
    text = comments[0]
    num_children = int(comments[1])
    children = []
    start = 2
    for _ in range(num_children):
        child_text, child_children = parse_comments(','.join(comments[start:]))
        children.append((child_text, child_children))
        start += len(child_children) + 2 if child_children else 2
    return text, children

def calculate_depth(node):
    if not node[1]:
        return 1
    else:
        return 1 + max(calculate_depth(child) for child in node[1])

def get_level_comments(node, level, comments_level):
    if level == 1:
        comments_level.append(node[0])
    else:
        for child in node[1]:
            get_level_comments(child, level - 1, comments_level)

