def solve():
    s = input()
    t = input()

    swaps = {}

    for i in range(len(s)):
        if s[i] != t[i]:
            if s[i] in swaps:
                if swaps[s[i]] != t[i]:
                    print(-1)
                    return
            elif t[i] in swaps:
                if swaps[t[i]] != s[i]:
