def solve():
    words = input().split()

    def is_valid_word(word):
        if word.endswith("lios") or word.endswith("liala") or word.endswith("etr") or word.endswith("etra") or word.endswith("initis") or word.endswith("inites"):
            return True
        return False

    def get_gender(word):
        if word.endswith("lios") or word.endswith("etr") or word.endswith("initis"):
            return "masculine"
        elif word.endswith("liala") or word.endswith("etra") or word.endswith("inites"):
            return "feminine"
        return None

    for word in words:
        if not is_valid_word(word):
            print("NO")
            return

    if not words:
        print("YES")
        return

    gender = get_gender(words[0])

    for word in words:
        if get_gender(word) != gender:
            print("NO")
            return

    noun_found = False
    noun_index = -1

    for i in range(len(words)):
        if words[i].endswith("etr") or words[i].endswith("etra"):
            if noun_found:
                print("NO")
                return
            noun_found = True
            noun_index = i

    if not noun_found:
        print("NO")
        return



    # Check adjectives before noun
    for i in range(noun_index):
        if not (words[i].endswith("lios") or words[i].endswith("liala")):
            print("NO")
            return

    # Check verbs after noun
    for i in range(noun_index + 1, len(words)):
        if not (words[i].endswith("initis") or words[i].endswith("inites")):
            print("NO")
            return

    print("YES")

