def solve():
    n, m = map(int, input().split())
    volunteers = []
    for _ in range(n):
        volunteers.append(input())

    dislikes = {}
    for _ in range(m):
        u, v = input().split()
        if u not in dislikes:
            dislikes[u] = set()
        if v not in dislikes:
            dislikes[v] = set()
        dislikes[u].add(v)
        dislikes[v].add(u)

    max_size = 0
    max_team = []

    for i in range(1 << n):
        team = []
        for j in range(n):
            if (i >> j) & 1:
                team.append(volunteers[j])

        is_independent = True
        for j in range(len(team)):
            for k in range(j + 1, len(team)):
                if team[j] in dislikes and team[k] in dislikes[team[j]]:
                    is_independent = False
                    break
            if not is_independent:
                break

        if is_independent:
            if len(team) > max_size:
                max_size = len(team)
                max_team = team
            elif len(team) == max_size and len(team) > 0:
                if sorted(team) < sorted(max_team):
                    max_team = team

    print(max_size)
    for member in sorted(max_team):
        print(member)

