def kth_permutation(n, k):
    factorials = [1] * (n + 1)
    for i in range(2, n + 1):
        factorials[i] = factorials[i - 1] * i

    numbers = list(range(1, n + 1))
    permutation = []
    k -= 1

    for i in range(n, 0, -1):
        index = k // factorials[i - 1]
        permutation.append(numbers[index])
        numbers.pop(index)
        k %= factorials[i - 1]

    return permutation

