        # Check for conflicts with existing activated colliders
        y = x
        while y > 1:
            if pr[y] in p:
                answer[i] = 'Conflict with ' + str(p[pr[y]])
                break
            y //= pr[y]
        else:
            # No conflict, activate the collider
            answer[i] = 'Success'
            d.add(x)
            # Update the dictionary p with the collider's prime factors
            y = x
            while y > 1:
                p[pr[y]] = x
                y //= pr[y]
    else:
        # Deactivate the collider
        if x in d:
            answer[i] = 'Success'
            y = x
            while y > 1:
                if pr[y] in p:
                    p.pop(pr[y])
                y //= pr[y]
            d.remove(x)
        else:
            answer[i] = 'Already off'

