    MOD = 1000000007

    adj_matrix = [
        [0, 1, 1, 1],
        [1, 0, 1, 1],
        [1, 1, 0, 1],
        [1, 1, 1, 0]
    ]

    def matrix_multiply(A, B):
        C = [[0, 0, 0, 0] for _ in range(4)]
        for i in range(4):
            for j in range(4):
                for k in range(4):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def matrix_power(A, n):
        result = [[0, 0, 0, 0] for _ in range(4)]
        for i in range(4):
            result[i][i] = 1

        while n > 0:
            if n % 2 == 1:
                result = matrix_multiply(result, A)
            A = matrix_multiply(A, A)
            n //= 2
        return result

