def solve():
    n = int(input())
    movements = []
    for _ in range(n):
        movements.append(input())

    possible_locations = set()
    possible_locations.add((0, 0))

    for movement in reversed(movements):
        new_locations = set()
        if movement == "UL":
            for x, y in possible_locations:
                new_locations.add((x, y + 1))
                new_locations.add((x - 1, y))
        elif movement == "UR":
            for x, y in possible_locations:
                new_locations.add((x, y + 1))
                new_locations.add((x + 1, y))
        elif movement == "DL":
