import heapq
import math

class DuplicatePriorityQueue:
    def __init__(self):
        self.heap = []

    def push(self, key, value):
        heapq.heappush(self.heap, (key, value))

    def pop(self):
        return heapq.heappop(self.heap)

    def empty(self):
        return len(self.heap) == 0

class Graph:
    def __init__(self, v = 0):
        self.adjacency_list = [[] for _ in range(v)]

    def add_vertex(self):
        self.adjacency_list.append([])

    def add_undirected_edge(self, u, v, weight = 1):
        self.adjacency_list[u].append((v, weight))
        self.adjacency_list[v].append((u, weight))

    def __getitem__(self, i):
        return self.adjacency_list[i]

    def __iter__(self):
        yield from self.adjacency_list

    def __len__(self):
        return len(self.adjacency_list)


def dijkstra(graph, source):
    distances = [math.inf for node in graph]
    distances[source] = 0
    pred = [None] * len(graph)
    priority_queue = DuplicatePriorityQueue()
    priority_queue.push(0, source)

    while not priority_queue.empty():
        # get minimum
        distance, v = priority_queue.pop()
        if distance > distances[v]: continue # duplicate in heap

        # update adjacent vertices
        for u, w in graph[v]:
            if distance + w < distances[u]:
                distances[u] = distance + w
                pred[u] = v
                priority_queue.push(distance + w, u)

    return distances, pred

def path(v, pred, labels, source = None):
    indexes = []
    current = v
    while current is not None:
        indexes.append(current)
        current = pred[current]
    if source is not None and indexes[-1] != source:
        raise ValueError('No path exists')
    return ' '.join(reversed(list(labels[i] for i in indexes)))

