def solve():
    n = int(input())
    parts = list(map(int, input().split()))
    dependencies = []
    for _ in range(n):
        dependencies.append(list(map(int, input().split())))

    cost = [[0, 1, 2],
            [2, 0, 1],
            [1, 2, 0]]

    def calculate_time(start_computer):
        time = 0
        current_computer = start_computer
        completed = [False] * n

        topological_order = []
        in_degree = [0] * n
        adj = [[] for _ in range(n)]

        for i in range(n):
            for dependency in dependencies[i][1:]:
                adj[dependency - 1].append(i)
                in_degree[i] += 1

        queue = []
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        while queue:
            u = queue.pop(0)
            topological_order.append(u)

            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        if len(topological_order) != n:
            return float('inf')

        for part_index in topological_order:
            required_computer = parts[part_index] - 1

            if current_computer != required_computer:
                time += cost[current_computer][required_computer]
                current_computer = required_computer

            time += 1
            completed[part_index] = True

        return time

    min_time = min(calculate_time(0), calculate_time(1), calculate_time(2))
    print(min_time)

solve()

