def prime_factorization(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            if d not in factors:
                factors[d] = 0
            factors[d] += 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = 1
    return factors

def euler_totient(n):
    factors = prime_factorization(n)
    result = n
    for p in factors:
        result *= (1 - 1/p)
    return int(result)

def solve():
    p = int(input())
    print(euler_totient(p - 1))

