                        assignment[i] = perm_num
                        perm_counts[perm_num] += 1
                        assigned = True
                        break

                if not assigned:
                    break

            if all(assignment[i] != 0 for i in range(n)):
                print(k)
                print(*assignment)
                return

    print(-1)

