def solve():
    n = int(input())
    guesses = []
    for _ in range(n):
        guess, bulls, cows = map(int, input().split())
        guesses.append((guess, bulls, cows))

    def is_valid(num):
        s = str(num).zfill(4)
        return len(set(s)) == 4

    def calculate_bulls_cows(guess, secret):
        guess_str = str(guess).zfill(4)
        secret_str = str(secret).zfill(4)
        bulls = 0
        cows = 0
        for i in range(4):
            if guess_str[i] == secret_str[i]:
                bulls += 1
            elif guess_str[i] in secret_str:
