def solve():
    user_name = input()
    n = int(input())
    priority = {}

    for _ in range(n):
        action = input()
        parts = action.split()
        x = parts[0]

        if "posted" in action:
            y = parts[-1].replace("'s", "")
            if x != user_name:
                priority[x] = priority.get(x, 0) + 15
            if y != user_name:
                priority[y] = priority.get(y, 0) + 15
        elif "commented" in action:
            y = parts[-1].replace("'s", "")
