        if n % 3 != 0:
            return False
        stripe_height = n // 3
        colors = set()
        for i in range(3):
            stripe = flag[i * stripe_height:(i + 1) * stripe_height]
            color = stripe[0][0]
            for row in stripe:
                if row[0] != color:
                    return False
            colors.add(color)
        return len(colors) == 3

    def check_vertical():
        if m % 3 != 0:
            return False
        stripe_width = m // 3
        colors = set()
        for i in range(3):
            color = flag[0][i * stripe_width]
            for row in flag:
                if row[i * stripe_width] != color:
                    return False
            colors.add(color)
        return len(colors) == 3

    if check_horizontal() or check_vertical():
        print("YES")
    else:
        print("NO")

